"""Data exploration -> reports/findings.md. Every number here is computed from the CSV.
Run: python -m oytra.analysis"""
import os, pandas as pd
from .data import load
from .llm import RuleJudge
from .config import ROOT, load_econ

def tbl(g, n=None):
    t = g.agg(orders=("rto", "size"), rto_rate=("rto", "mean")).sort_values("rto_rate", ascending=False)
    t["rto_rate"] = (t.rto_rate * 100).round(1).astype(str) + "%"
    return (t.head(n) if n else t).to_markdown() if hasattr(t, "to_markdown") else t.to_string()

def main():
    rep = {}; d = load(report=rep); e = load_econ(); J = RuleJudge()
    jj = [J.judge(r.customer_name, r.address, r.city, r.pincode) for r in d.itertuples()]
    d["addr_kind"] = [j["address_kind"] for j in jj]; d["fake_name"] = [j["name_fake"] for j in jj]
    d["hinglish"] = [j["hinglish"] for j in jj]
    d["first_time"] = d.customer_prior_orders == 0; d["hour"] = d.dt.dt.hour
    pin = d[d.pincode != ""].groupby("pincode").size()
    L = []; w = L.append
    w("# Data findings (auto-generated by `python -m oytra.analysis`)\n")
    w(f"Cleaned dataset: {rep['rows_clean']} labelled COD orders, {d.dt.min():%d %b %Y} – {d.dt.max():%d %b %Y}. "
      f"Overall RTO {d.rto.mean():.1%} ({d.rto.sum()} orders). Average order value in data ₹{d.order_value.mean():.0f} (brief says ₹{e['brief_aov']}).\n")
    w(f"Cleaning: {rep['exact_duplicates_removed']} exact duplicate rows removed; status labels normalised (e.g. 'Rto', 'delivered'); "
      f"{rep['unlabelled_removed']} IN_TRANSIT order dropped; {rep['missing_pincode']} missing pincodes, {rep['missing_city']} missing cities, "
      f"{rep['bad_phone']} phones that are not 10-digit mobiles, {rep['zero_value_orders']} ₹0 orders, "
      f"{rep['prior_rto_gt_prior_orders']} rows where prior RTOs > prior orders (kept, flagged).\n")
    w(f"\n## 1. Pincode history is too thin to 'stop COD in bad pincodes'\n{pin.size} distinct pincodes for {len(d)} orders; "
      f"median {pin.median():.0f} order per pincode, {(pin == 1).mean():.0%} of pincodes have exactly one order, only {(pin >= 5).sum()} have 5+. "
      f"A pincode with 1 RTO out of 1 looks '100% bad' but is noise. State and city carry the real signal:\n\n{tbl(d.groupby('state'))}\n\n"
      f"Worst cities:\n\n{tbl(d.groupby('city'), 6)}\n")
    w(f"\n## 2. Bad addresses are the strongest single red flag — Hinglish is NOT\n{tbl(d.groupby('addr_kind'))}\n\n"
      f"'unusable' = '.', 'xyz', 'call me', 'near station', 'home' or just a city name. Hinglish landmark addresses "
      f"(e.g. 'Hanuman Mandir ke saamne'): {d[d.hinglish].rto.mean():.1%} RTO on {d.hinglish.sum()} orders vs {d[~d.hinglish].rto.mean():.1%} for the rest — "
      "so the LLM must judge *completeness*, not penalise language.\n")
    w(f"\n## 3. Fake names exist and mostly refuse\n{d.fake_name.sum()} orders with names like 'Test Order', 'qwerty', 'asdf', 'aaa': "
      f"{d[d.fake_name].rto.mean():.1%} RTO vs {d[~d.fake_name].rto.mean():.1%} for real names. Top: "
      f"{', '.join(f'{k} ({v})' for k, v in d[d.fake_name].customer_name.value_counts().head(5).items())}.\n")
    g = d.groupby("first_time").rto.agg(["mean", "size"])
    w(f"\n## 4. First-time buyers are riskier, but not 'cancel' risky; past refusers are\n"
      f"First-time: {g.loc[True,'mean']:.1%} RTO ({g.loc[True,'size']} orders, {d.first_time.mean():.0%} of all). Repeat: {g.loc[False,'mean']:.1%} ({g.loc[False,'size']}).\n\n"
      f"By prior RTOs:\n\n{tbl(d.groupby('customer_prior_rto'))}\n\n"
      f"First-time buyers by channel:\n\n{tbl(d[d.first_time].groupby('utm_source'))}\n")
    w(f"\n## 5. Things that do NOT matter much (so we don't build rules on them)\n"
      f"Hour of day:\n\n{tbl(d.groupby(pd.cut(d.hour, [-1, 5, 11, 17, 21, 23], labels=['00-05', '06-11', '12-17', '18-21', '22-23'])))}\n\n"
      f"Order value:\n\n{tbl(d.groupby(pd.qcut(d.order_value, 5)))}\n\nCourier:\n\n{tbl(d.groupby('courier'))}\n\nItems in order:\n\n{tbl(d.groupby('num_items'))}\n")
    L_ = e["rto_loss"]; V = e["gross_margin"] * e["brief_aov"] - e["forward_shipping"] - e["packaging_handling"]
    w(f"\n## 6. The money: a delivered order is worth ~2-4x an RTO loss\nRTO loss = ₹65+₹65+₹25+8%×₹180 = ₹{L_:.1f}. "
      f"A delivered ₹{e['brief_aov']} order earns 62% margin minus ₹90 shipping+packing = ₹{V:.1f}. The ₹{e['cac']} CAC is acquisition spend already made, not value created by delivering, so it is NOT added. "
      f"Cancelling only pays when RTO risk exceeds V/(V+L) = {V/(V+L_):.0%} (same for first-time and repeat buyers). "
      f"At the brief's 28% COD RTO, each COD order loses on average ₹{0.28*L_:.1f} to RTO.\n")
    # 7. products & item count
    pl = d.products
    rows = []
    for prod in sorted({x.strip() for l in pl for x in l if x.strip()}):
        m = pl.apply(lambda l: prod in [x.strip() for x in l])
        rows.append({"product": prod, "orders_containing": int(m.sum()), "rto_rate": f"{d[m].rto.mean():.1%}",
                     "solo_orders": int((m & (d.num_items == 1)).sum()), "rto_rate_when_solo": f"{d[m & (d.num_items == 1)].rto.mean():.1%}",
                     "share_in_multi_item_orders": f"{(m & (d.num_items > 1)).sum() / m.sum():.0%}"})
    pt = pd.DataFrame(rows).sort_values("orders_containing", ascending=False).set_index("product")
    w(f"\n## 7. Products and basket size: a finding, not a rule\nItems in order (validated: `num_items` vs parsed product list disagreed on "
      f"{rep['num_items_mismatch']} rows; rule if they ever disagree: trust the parsed list, keep the reported value):\n\n{tbl(d.groupby('num_items'))}\n\n"
      f"By product (an order with 2 items counts under both, so rows overlap and do not add up to {len(d)}; the solo column isolates single-item orders):\n\n"
      f"{pt.to_markdown() if hasattr(pt, 'to_markdown') else pt.to_string()}\n\n"
      f"Basket size is not monotonic: 1 item {d[d.num_items == 1].rto.mean():.1%}, 2–3 items {d[d.num_items.isin([2, 3])].rto.mean():.1%}, 4 items {d[d.num_items == 4].rto.mean():.1%} "
      f"(only {(d.num_items == 4).sum()} orders). The model keeps the simple `single_item` flag. Product differences mostly overlap with basket size and value "
      "(over 70% of each product's orders are multi-item); adding 8 product flags to the model did not reliably help (section 9). **Rule: we never cancel or hold an order because of "
      "which product it contains.** Product mix may later steer *which* prepaid offer to show, never whether to ship.\n")
    # 8. customer-history audit
    from .variants import history_audit
    h = history_audit(d)
    w(f"\n## 8. Customer-history fields: inconsistent with the file, kept with care\n"
      f"`customer_prior_orders` / `customer_prior_rto` come with each order (like Shopify customer fields). Checked against the same phone's earlier orders in this file "
      f"(only outcomes ≥{h['outcome_lag_days_used']} days old counted as known):\n\n"
      f"- {h['phones_with_more_than_one_order']} phones place more than one order ({h['orders_on_those_phones']} orders).\n"
      f"- {h['reported_prior_orders_below_orders_visible_in_file']} orders report fewer prior orders than the file itself shows; "
      f"{h['reported_first_time_but_earlier_order_in_file']} say 'first-time' although an earlier order exists; on {h['phones_where_reported_prior_orders_goes_down']} phones the count goes *down* over time.\n"
      f"- {h['later_orders_after_an_rto_in_file']} orders follow a known RTO on the same phone; only {h['   of_which_report_prior_rto_above_0']} report prior RTO > 0.\n"
      f"- {h['rows_prior_rto_gt_prior_orders']} rows have prior RTO > prior orders; {h['   of_which_rto']} of them are RTO.\n"
      f"- Where the file shows no earlier order, RTO by reported prior RTO: {', '.join(f'{k} → {v}' for k, v in h['rto_rate_by_reported_prior_rto_when_file_shows_no_history'].items())}.\n"
      f"- Real in-file history points the same way, more weakly: after a known RTO the next order is {h['rto_rate_after_previous_order_in_file']['previous_rto_known']:.1%} RTO vs "
      f"{h['rto_rate_after_previous_order_in_file']['previous_delivered']:.1%} after a delivery.\n\n"
      "Reading: the file is a ~2,000-order sample covering six months of a store with ~1,650 COD orders a month, so missing history is expected; counts that fall over time are not, so the fields are noisy, "
      "Root cause in section 10: the counts follow order_id order, not time order (a source-data issue, not our parsing). The 13/14 cell is a small-n warning sign of possible leakage, not proof. Decision and model comparison in section 9.\n")
    vp = os.path.join(ROOT, "reports", "model_variants.json")
    if os.path.exists(vp):
        import json; V_ = json.load(open(vp))["variants"]
        vt = pd.DataFrame(V_).T[["test_auc", "cv_auc_train", "brier", "september_net_rupees_base_case"]]
        vt.columns = ["Sep test AUC", "Apr–Aug CV AUC", "Brier", "Sep est. net ₹ (base)"]
        ci = {k: v.get("test_auc_change_95pct_ci") for k, v in V_.items() if v.get("test_auc_change_95pct_ci")}
        w(f"\n## 9. Model with / without history and products (`python -m oytra.variants`)\n{vt.to_markdown() if hasattr(vt, 'to_markdown') else vt.to_string()}\n\n"
          f"Bootstrap 95% CI of the AUC change vs production: {'; '.join(f'{k}: {v[0]:+.3f} to {v[1]:+.3f}' for k, v in ci.items())}.\n\n"
          "Decision: keep the reported history (available at order time, worth ~0.05 AUC, leakage not shown) but treat 'no history' as the robustness floor: "
          "it still nets positive while the ops rule loses heavily. Products: CI crosses zero and ₹ falls, so not added. Item count as a number: no gain over `single_item`. "
          "Before go-live, check the fields against OYTRA's own Shopify customer records.\n")
    J = lambda n: json.load(open(os.path.join(ROOT, "reports", n))) if os.path.exists(os.path.join(ROOT, "reports", n)) else None
    import json
    rc = J("history_rootcause.json")
    if rc:
        a, b, c, dd, e = rc["a_parse_and_sort"], rc["b_shared_phone"], rc["c_counter_reset"], rc["d_source_field"], rc["e_order_id_sequence"]
        sh = dd["phones_decreasing_observed_vs_if_values_were_shuffled_randomly"]
        w(f"\n## 10. Root cause of the history inconsistency (`python -m oytra.history_rootcause`)\n"
          f"- **Our parse/sort?** No. {a['rows_matching_single_format_YYYY-MM-DD_HH:MM']} timestamps share one format, {a['parse_failures']} parse failures; we sort by parsed time with order_id as a stable tie-break. "
          f"Prior-RTO decreases on {a['phones_prior_rto_decreasing_time_sorted']} phones (the earlier figure of 74 is reproduced exactly when grouping by the raw phone string: {a['phones_prior_rto_decreasing_grouped_by_raw_phone_string']}; normalising '+91'/'0' prefixes joins one more customer. Same-minute ties don't change it: {a['phones_prior_rto_decreasing_excluding_same_minute_ties']}), prior-orders on {a['phones_prior_orders_decreasing_time_sorted']}.\n"
          f"- **One phone, different people?** No. Of {b['phones_with_2plus_orders']} repeat phones only {b['with_more_than_one_name']} carry more than one name and {b['with_more_than_one_city']} more than one city ({b['with_more_than_one_pincode']} have different pincodes: same person, varying address). "
          f"{b['name_city_pairs_seen_on_more_than_one_phone']} name+city pairs appear on several phones, mostly common names, so name is not a key.\n"
          f"- **Counter reset?** Not cleanly: {c['drops_in_prior_orders']} drops, {c['drops_to_zero']} to 0 (0 is 75% of all values anyway) and {c['drops_to_nonzero']} to another non-zero value.\n"
          f"- **Source data: yes.** Sorted by timestamp, {sh['prior_orders'][0]} phones have a falling count, about what random shuffling gives ({sh['prior_orders'][1]}); prior RTO {sh['prior_rto'][0]} vs {sh['prior_rto'][1]}. "
          f"Sorted by **order_id**, only {e['by_order_id']['negative_steps']} of {e['by_order_id']['steps']} steps go down (vs {e['by_timestamp']['negative_steps']} by time) and the count is ≥ the order's position {e['by_order_id']['reported_count_at_least_position']:.0%} of the time (vs {e['by_timestamp']['reported_count_at_least_position']:.0%}). "
          f"Within a phone, a later timestamp has a higher order_id only {e['same_phone_order_id_increases_with_time_share']:.0%} of the time. Single-order phones report 'first-time' {dd['reported_first_time_share']['single_order_phones']:.1%} of the time.\n\n"
          f"**Verdict:** {rc['verdict']} Exposure: {e['september_orders_whose_phone_has_a_lower_id_order_timestamped_later']} of {e['september_orders']} September orders have a same-phone order with a lower ID but a later timestamp, so the possible look-ahead is small; the no-history model (section 9) stays the worst case.\n\n"
          "**Identifying first-time customers reliably:** " + " ".join(f"({i+1}) {s}" for i, s in enumerate(rc["how_to_identify_first_time_customers"])) + "\n")
    la = J("leakage_audit.json")
    if la:
        lg = la["5_label_lag"]
        w(f"\n## 11. Temporal leakage audit of the pincode/state encoding (`python -m oytra.leakage_audit`)\n"
          f"- Encoders used to score September are fit on Apr–Aug only (latest training date {la['1_encoder_fit_rows_latest_date']}). Flipping every September label leaves September scores unchanged: {la['2_sept_scores_unchanged_when_sept_labels_flipped']}.\n"
          f"- Training rows get a chronological (earlier-orders-only, weekly expanding) pin feature: {la['3_training_rows_whose_own_label_moves_their_pin_feature (of 20)']} of 20 sampled rows move when their own label is flipped, and {la['3_earlier_rows_moved_by_a_later_label (20 flips)']} earlier rows move when a later label is flipped. ({la['3_note']}.)\n"
          f"- CV for threshold choice re-fits encoders inside each fold: fold-0 predictions unchanged when fold-0 labels are flipped: {la['4_cv_fold0_predictions_unchanged_when_fold0_labels_flipped']}. Folds are random within Apr–Aug ({la['4_cv_folds']}).\n"
          f"- Label lag (production realism): only {lg['train_rows_outcome_known_by_1_sep']:,} of {lg['train_rows_all']:,} training outcomes would be known {lg['lag_days']} days before 1 Sep. Training on those only: September AUC {lg['sept_auc_lagged_train']} vs {lg['sept_auc_all_train']}, net ₹{lg['sept_net_lagged_train']:,} vs ₹{lg['sept_net_all_train']:,}.\n\n"
          f"**Verdict:** {la['verdict']} No headline number changes. In production, retrain only on matured outcomes.\n")
    bt = J("backtest.json")
    if bt and "september_metrics" in bt["model"]:
        sm, rb = bt["model"]["september_metrics"], bt["september_risk_buckets"]
        w(f"\n## 12. Evaluation metrics, September (329 orders, {bt['test']['rto_orders']} RTO)\n"
          f"- ROC-AUC {bt['model']['test_auc']}. **PR-AUC (average precision) {sm['pr_auc_average_precision']}** vs a base rate of {sm['base_rate']} (what a random ranking would score).\n"
          f"- **Brier {sm['brier']}** vs {sm['brier_if_always_base_rate']} for always predicting the base rate.\n"
          f"- Majority-class accuracy {sm['majority_class_accuracy']:.2%}: context only. Saying 'delivered' to everyone is this accurate and saves ₹0, which is why we judge in ₹.\n\n"
          "| Risk bucket | Orders | RTO | Mean predicted | Actual RTO rate |\n|---|---|---|---|---|\n" +
          "\n".join(f"| {r['bucket']} | {r['orders']} | {r['rto']} | {r['mean_predicted']:.1%} | {r['actual_rto_rate']:.1%} |" for r in rb if r['orders']) +
          "\n\nCalibration chart: `reports/calibration.png` (SVG source `reports/calibration.svg`). The model is well calibrated in the buckets with enough orders; the top two buckets are small (16 and 2 orders).\n")
    ab = J("ablation.json")
    if ab:
        rows = ab["rows"]; base = rows[0]
        w("\n## 13. Feature ablation (`python -m oytra.ablation`, full table in `reports/ablation.md`)\n"
          "Same Apr–Aug → Sep split, same thresholds; one feature or group removed at a time.\n\n"
          "| Variant | AUC | ΔAUC | PR-AUC | Brier | Sep net ₹ |\n|---|---|---|---|---|---|\n" +
          "\n".join(f"| {r['variant']} | {r['test_auc']:.3f} | {r['delta_auc']:+.3f} | {r['pr_auc']:.3f} | {r['brier']:.4f} | {r['september_net_rupees']:,} |" for r in rows if r['variant'].startswith(('full', 'group'))) +
          "\n\nReading: address/name/phone quality, area (pincode/state) and reported customer history each carry ~0.04–0.06 AUC; value+night ~0.01; single features like `night`, `name_fake` (also a hard rule) "
          "and `phone_invalid` add ~nothing to AUC. ₹ moves by a few hundred either way, within one month's noise, and sometimes rises when AUC falls (the hard address/name rules still act on those orders). "
          "No feature is removed on one month's evidence; `phone_invalid` is the first candidate to drop if the next month agrees.\n")
    os.makedirs(os.path.join(ROOT, "reports"), exist_ok=True)
    open(os.path.join(ROOT, "reports", "findings.md"), "w").write("\n".join(L))
    print("\n".join(L))

if __name__ == "__main__":
    main()
